import{_ as a,c as e,o as t,a1 as i}from"./chunks/framework.7AAjiCkA.js";const u=JSON.parse('{"title":"AI实验室","description":"","frontmatter":{},"headers":[],"relativePath":"快速使用/AI实验室.md","filePath":"快速使用/AI实验室.md"}'),o={name:"快速使用/AI实验室.md"},s=i('<h1 id="ai实验室" tabindex="-1">AI实验室 <a class="header-anchor" href="#ai实验室" aria-label="Permalink to &quot;AI实验室&quot;">​</a></h1><p>AI实验室是为BASETEC用户提供的最先进的AI衍生服务，如AI视频创作、图片创作、AI语音生成、音色克隆、照片修复等内容。AI实验室绑定BASETEC用户体系，采用账户余额制。</p><h2 id="stable-diffusion-ai生图服务" tabindex="-1">Stable Diffusion AI生图服务 <a class="header-anchor" href="#stable-diffusion-ai生图服务" aria-label="Permalink to &quot;Stable Diffusion AI生图服务&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Stable Diffusion</p><p>Stable Diffusion 是一种基于深度学习的图像生成模型。与其他生成模型相比，Stable Diffusion 能够生成更高质量、更细节丰富的图像，同时可以用于各种图像生成任务，如图像修复、图像超分辨率、图像生成等。</p></div><h3 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h3><p>前往BASETEC官网并登录，进入个人中心，在功能区中选择 <code>AI实验室</code> 。</p><p>该功能与大语言模型生图的区别：支持更专业的参数调校、更可控的风格和效果以及更低的资费，并且可以永久存储。</p><p>您生成的图像将为您持续保存，您可以在个人中心查看、下载、分享您的图像。</p><h3 id="资费" tabindex="-1">资费 <a class="header-anchor" href="#资费" aria-label="Permalink to &quot;资费&quot;">​</a></h3><p>目前该功能处于公测阶段，暂不收费。</p>',10),r=[s];function l(n,c,d,_,f,h){return t(),e("div",null,r)}const A=a(o,[["render",l]]);export{u as __pageData,A as default};
